import React, { useState } from 'react';

export default function ReturnModal({ open, refCode, onCancel, onConfirm }) {
  const [reason, setReason] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  if (!open) return null;

  const handleConfirm = async () => {
    if (!reason.trim()) {
      alert('Please enter a reason for returning this document.');
      return;
    }
    setIsSubmitting(true);
    try {
      await onConfirm(reason.trim());
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && e.ctrlKey) {
      handleConfirm();
    }
  };

  return (
    <div className="overlay" onClick={e => e.target === e.currentTarget && !isSubmitting && onCancel && onCancel()}>
      <div className="modal" style={{ maxWidth: 520 }}>
        <div className="modal-head">
          <div className="modal-title">Return Document</div>
          <button 
            className="btn btn-outline btn-sm" 
            onClick={onCancel}
            disabled={isSubmitting}
          >
            ✕
          </button>
        </div>
        <div className="modal-body">
          <div style={{ fontSize: 14, color: 'var(--t1)', marginBottom: 12 }}>
            You are returning document <strong>{refCode}</strong>. Please provide a reason for the return:
          </div>
          <textarea
            className="inp"
            placeholder="Enter reason for returning this document (e.g., Missing signature, Document locked, etc.)"
            value={reason}
            onChange={e => setReason(e.target.value)}
            onKeyDown={handleKeyDown}
            disabled={isSubmitting}
            style={{
              width: '100%',
              height: '100px',
              padding: '8px 12px',
              borderRadius: '4px',
              border: '1px solid var(--border)',
              fontFamily: 'inherit',
              fontSize: '14px',
              resize: 'vertical'
            }}
          />
          <div style={{ fontSize: 12, color: 'var(--t3)', marginTop: 8 }}>
            Only the user assigned to <strong>Mark IN</strong> role can re-scan this document.
          </div>
        </div>
        <div className="modal-foot" style={{ display: 'flex', gap: 8 }}>
          <button 
            className="btn btn-outline" 
            onClick={onCancel}
            disabled={isSubmitting}
          >
            Cancel
          </button>
          <button 
            className="btn btn-amber" 
            onClick={handleConfirm}
            disabled={isSubmitting}
          >
            {isSubmitting ? 'Returning...' : '↩️ Return'}
          </button>
        </div>
      </div>
    </div>
  );
}
